export function getKeywordsByCountry(countryCode: string): GlobalKeywordItem[] {
  return GLOBAL_KEYWORDS_DATABASE.filter(k => k.countryCode.toLowerCase() === countryCode.toLowerCase());
}

export function getKeywordsByService(service: string): GlobalKeywordItem[] {
  return GLOBAL_KEYWORDS_DATABASE.filter(k => k.serviceCategory.toLowerCase().includes(service.toLowerCase()));
}

export function getDubaiKeywords(): GlobalKeywordItem[] {
  return GLOBAL_KEYWORDS_DATABASE.filter(k => k.countryCode === "AE");
}

export function getKeywordsByIntent(intent: "Transactional" | "Commercial" | "Informational" | "Local"): GlobalKeywordItem[] {
  return GLOBAL_KEYWORDS_DATABASE.filter(k => k.intent === intent);
}
